package com.google.javascript.jscomp;

import com.google.common.base.Preconditions;
import com.google.common.collect.Lists;
import com.google.common.collect.Maps;
import com.google.common.collect.Sets;
import com.google.javascript.jscomp.AbstractCompiler.LifeCycleStage;
import com.google.javascript.jscomp.MakeDeclaredNamesUnique.BoilerplateRenamer;
import com.google.javascript.jscomp.NodeTraversal.AbstractPostOrderCallback;
import com.google.javascript.jscomp.NodeTraversal.Callback;
import com.google.javascript.jscomp.Scope.Var;
import com.google.javascript.jscomp.testing.CompilerTestCase;
import com.google.javascript.jscomp.testing.TestEval;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Map;
import java.util.Set;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Normalize_process_TriageGen2Test extends CompilerTestCase {

  /**
   * Tests the standard flow where MAKE_LOCAL_NAMES_UNIQUE is true.
   * This covers the branch where the renamer is executed.
   */
  @Test
  public void testProcess_WithMakeLocalNamesUniqueTrue() throws Exception {
    // We use a code snippet that triggers the logic described in the comments:
    // A catch block variable 'e' that conflicts with a function scope 'e'.
    String code = "function f() { try { throw 0; } catch(e) { e; } var e = 1; }";
    Compiler compiler = new Compiler();
    SourceFile input = parseCode(code);
    Node externs = new Node(Token.MISSING);
    Node root = compiler.compile(externs, input).getRoot();

    // Since MAKE_LOCAL_NAMES_UNIQUE is a static field in Normalize, 
    // its value depends on the environment/configuration. 
    // We assume the standard behavior for this test.
    Normalize normalize = new Normalize(compiler, false);
    normalize.process(externs, root);

    // Verify the compiler reached the NORMALIZED stage
    assertNotNull(compiler.getLifeCycleStage());
    // The code should have been processed without throwing exceptions
  }

  /**
   * Tests the flow where MAKE_LOCAL_NAMES_UNIQUE might be false.
   * This covers the branch where the renamer is skipped.
   */
  @Test
  public void testProcess_WithMakeLocalNamesUniqueFalse() throws Exception {
    // Set the static flag to false to hit the alternative branch
    // Note: In a real environment, this might require reflection if it's private/final,
    // but here we follow the logic provided in the snippet.
    Normalize.MAKE_LOCAL_NAMES_UNIQUE = false;

    String code = "var x = 1; function x() {}";
    Compiler compiler = new Compiler();
    SourceFile input = parseCode(code);
    Node externs = new Node(Token.MISSING);
    Node root = compiler.compile(externs, input).getRoot();

    Normalize normalize = new Normalize(compiler, false);
    normalize.process(externs, root);

    // Verify lifecycle stage updated
    assertTrue(compiler.getLifeCycleStage().isNormalized());
  }

  /**
   * Tests the lifecycle stage transition logic.
   */
  @Test
  public void testProcess_LifecycleStageTransition() throws Exception {
    Compiler compiler = new Compiler();
    // Manually set a non-normalized stage if possible, or simulate via a fresh compiler
    // In Closure Compiler, a fresh compiler starts at a stage that is not normalized.

    String code = "var a = 1;";
    SourceFile input = parseCode(code);
    Node externs = new Node(Token.MISSING);
    Node root = compiler.compile(externs, input).getRoot();

    Normalize normalize = new Normalize(compiler, false);

    // Ensure it's not normalized before
    if (compiler.getLifeCycleStage().isNormalized()) {
        // This part is tricky because compiler state is internal, 
        // but the logic is: if (!isNormalized) { set(NORMALIZED) }
    }

    normalize.process(externs, root);

    // Verify the side effect: stage is now NORMALIZED
    assertEquals(LifeCycleStage.NORMALIZED, compiler.getLifeCycleStage());
  }

  /**
   * Tests a simple case to ensure the NodeTraversal and PropagateConstantAnnotations 
   * do not crash on empty/minimal input.
   */
  @Test
  public void testProcess_MinimalInput() throws Exception {
    Compiler compiler = new Compiler();
    SourceFile input = parseCode("");
    Node externs = new Node(Token.MISSING);
    Node root = compiler.compile(externs, input).getRoot();

    Normalize normalize = new Normalize(compiler, false);
    normalize.process(externs, root);

    assertTrue(compiler.getLifeCycleStage().isNormalized());
  }
}
